let saldo = 100;
let continuar = true;

do {
    let opcao = prompt("1-Saldo  2-Sacar  3-Depositar  0-Sair");

    if (opcao === "0") {
        continuar = false;
    } else if (opcao === "1") {
        console.log("Saldo: R$ " + saldo);
    } else if (opcao === "2") {
        let valor = Number(prompt("Valor do saque:"));
        if (valor <= 0 || valor > saldo) {
            console.log("Valor inválido.");
            continue;
        }
        saldo -= valor;
        console.log("Saque feito. Saldo: R$ " + saldo);
    } else if (opcao === "3") {
        let valor = Number(prompt("Valor do depósito:"));
        saldo += valor;
        console.log("Depósito feito. Saldo: R$ " + saldo);
    } else {
        console.log("Opção inválida.");
    }
} while (continuar);

